-- Older saved housing positions predate the library's explicit coordinate spaces.
function Adapter:SavedPosition(value)
    if type(value) ~= "table" then return nil end
    if value.pos then
        value = {
            space = value.isUI and "map" or "world",
            x = value.pos.x,
            y = value.pos.y,
            z = value.pos.z,
            uiMapID = value.isUI and value.mapId or value.uiMapID,
            instanceID = not value.isUI and value.mapId or nil,
        }
    end
    value = Copy(value)
    value.region = nil -- Re-evaluate saved observations against current access data.
    return APR.NavigationData:NormalizeLocation(value)
end--[[APR_DIAG]]; Adapter.SavedPosition = APRTrace("APR-Core/features/navigation/adapter/NavigationAdapterLocations.lua:22:Adapter:SavedPosition#1", Adapter.SavedPosition)--[[/APR_DIAG]]

local function ReadableBindPosition(position)
    if
        not Accessible(position)
        or type(position) ~= "table"
        or (APR.CanAccessTable and not APR:CanAccessTable(position))
    then
        return false
    end
    for _, key in ipairs(Constants.BIND_LOCATION_FIELDS) do
        local value = position[key]
        if not Accessible(value) then return false end
        local kind = type(value)
        if kind ~= "nil" and kind ~= "string" and kind ~= "boolean" and not Number(value) then return false end
    end
    return Number(position.x)
        and Number(position.y)
        and (position.z == nil or Number(position.z))
        and (position.instanceID == nil or Number(position.instanceID))
        and (position.uiMapID == nil or Number(position.uiMapID))
end--[[APR_DIAG]]; ReadableBindPosition = APRTrace("APR-Core/features/navigation/adapter/NavigationAdapterLocations.lua:39:ReadableBindPosition#2", ReadableBindPosition)--[[/APR_DIAG]]

local BindLookup = {}
BindLookup.__index = BindLookup

function BindLookup:Cancel()
    self.status = "cancelled"
end--[[APR_DIAG]]; BindLookup.Cancel = APRTrace("APR-Core/features/navigation/adapter/NavigationAdapterLocations.lua:63:BindLookup:Cancel#3", BindLookup.Cancel)--[[/APR_DIAG]]

function BindLookup:Step(maxOperations, maxMilliseconds)
    if self.status ~= "planning" then return self.status end
    if Text(Call(GetBindLocation)) ~= self.name then
        self:Cancel()
        return self.status
    end
    local deadline = self.clock and (self.clock() + (maxMilliseconds or 1))
    for operation = 1, maxOperations or 32 do
        if operation > 1 and deadline and self.clock() >= deadline then break end
        local id, definition = next(self.bindings, self.cursor)
        self.cursor = id
        if not id then
            -- Missing area data gets another chance on the next world load.
            -- Keep the negative result for this session so each hearth variant
            -- does not restart the same scan.
            Adapter.bindLookup = { name = self.name, position = self.found or false }
            self.status = "ready"
            break
        end
        -- Several inns can share one area ID. Named candidate keys preserve all
        -- locations; old consumers may still supply tables keyed by area ID.
        local areaID = Number(definition.areaID) and definition.areaID or (Number(id) and id)
        local areaName = areaID and Text(C_Map and Call(C_Map.GetAreaInfo, areaID))
        if areaName == self.name then
            -- Normalization itself reads access fields while identifying the
            -- region. An unreadable candidate cannot be ignored in favor of a
            -- readable inn with the same name.
            local position = ReadableBindPosition(definition) and APR.NavigationData:NormalizeLocation(definition)
            local ambiguous = not position or not ReadableBindPosition(position)
            local found = self.found
            if not ambiguous and found then
                for _, key in ipairs(Constants.BIND_ACCESS_FIELDS) do
                    if found[key] ~= position[key] then
                        ambiguous = true
                        break
                    end
                end
                local distanceSquared = (found.x - position.x) ^ 2 + (found.y - position.y) ^ 2
                ambiguous = ambiguous or distanceSquared > 25
            end
            if not ambiguous and position.z ~= nil then
                -- An old representative without altitude must not hide two
                -- later, conflicting heights. Keep a separate known-height
                -- reference without inventing an altitude for the result.
                local known = self.knownHeightPosition
                if known then
                    ambiguous = (known.x - position.x) ^ 2 + (known.y - position.y) ^ 2 + (known.z - position.z) ^ 2
                        > 25
                else
                    self.knownHeightPosition = position
                end
            end
            if ambiguous then
                -- Matching XY alone cannot identify a floor, phase or sealed
                -- room. A confirmed observation is required to disambiguate.
                Adapter.bindLookup = { name = self.name, position = false }
                self.status = "ready"
                break
            end
            -- Keep one representative: successive nearby candidates must not
            -- move the tolerance window arbitrarily far from the result.
            self.found = found or position
        end
    end
    return self.status
end--[[APR_DIAG]]; BindLookup.Step = APRTrace("APR-Core/features/navigation/adapter/NavigationAdapterLocations.lua:67:BindLookup:Step#4", BindLookup.Step)--[[/APR_DIAG]]

function Adapter:CreatePreparation(context)
    local name = Text(Call(GetBindLocation))
    local observed = self:GetCharacterSettings().bindLocation
    local cached = self.bindLookup
    local known = not name
        or (cached and cached.name == name)
        or (observed and observed.name == name and self:SavedPosition(observed.location))
    return setmetatable({
        status = known and "ready" or "planning",
        name = name,
        clock = context and context.clock,
        bindings = APR.NavigationData:GetBindings(),
    }, BindLookup)
end--[[APR_DIAG]]; Adapter.CreatePreparation = APRTrace("APR-Core/features/navigation/adapter/NavigationAdapterLocations.lua:134:Adapter:CreatePreparation#5", Adapter.CreatePreparation)--[[/APR_DIAG]]

function Adapter:GetBindPosition()
    local name = Text(Call(GetBindLocation))
    if not name then return nil end
    local observed = self:GetCharacterSettings().bindLocation
    if observed and observed.name == name then
        local position = self:SavedPosition(observed.location)
        if position then return position end
    end
    if not self.bindLookup or self.bindLookup.name ~= name then
        -- Legacy callers can resolve synchronously. Navigation prepares this
        -- lookup through its budgeted job before requesting any transport edges.
        local lookup = self:CreatePreparation()
        while lookup:Step(64) == "planning" do
        end
    end
    local cached = self.bindLookup
    return cached and cached.name == name and cached.position and Copy(cached.position) or nil
end--[[APR_DIAG]]; Adapter.GetBindPosition = APRTrace("APR-Core/features/navigation/adapter/NavigationAdapterLocations.lua:149:Adapter:GetBindPosition#6", Adapter.GetBindPosition)--[[/APR_DIAG]]

function Adapter:CaptureBind()
    local name, position = Text(Call(GetBindLocation)), PlayerPosition()
    if name and position then
        self:GetCharacterSettings().bindLocation = { name = name, location = Copy(position) }
        self.bindLookup = nil
    end
end--[[APR_DIAG]]; Adapter.CaptureBind = APRTrace("APR-Core/features/navigation/adapter/NavigationAdapterLocations.lua:168:Adapter:CaptureBind#7", Adapter.CaptureBind)--[[/APR_DIAG]]

local function ValidHouse(house)
    return type(house) == "table" and Text(house.houseGUID) and Text(house.neighborhoodGUID) and Number(house.plotID)
end--[[APR_DIAG]]; ValidHouse = APRTrace("APR-Core/features/navigation/adapter/NavigationAdapterLocations.lua:176:ValidHouse#8", ValidHouse)--[[/APR_DIAG]]

function Adapter:GetHousingData()
    if not C_Housing then return nil end
    local settings = self:GetCharacterSettings()
    local wanted = Text(Call(C_Housing.GetTrackedHouseGuid)) or settings.selectedHouseGUID
    local fallback
    for _, house in ipairs(self.houses) do
        if ValidHouse(house) then
            if house.houseGUID == wanted then return house end
            fallback = fallback or house
        end
    end
    if fallback then settings.selectedHouseGUID = fallback.houseGUID end
    return fallback
end--[[APR_DIAG]]; Adapter.GetHousingData = APRTrace("APR-Core/features/navigation/adapter/NavigationAdapterLocations.lua:180:Adapter:GetHousingData#9", Adapter.GetHousingData)--[[/APR_DIAG]]

function Adapter:GetHousingPosition()
    local house = self:GetHousingData()
    if not house then return nil end
    local mapID = Call(C_Housing.GetUIMapIDForNeighborhood, house.neighborhoodGUID)
    if not Number(mapID) then return nil end
    local current = Text(Call(C_Housing.GetCurrentNeighborhoodGUID))
    local settings = self:GetCharacterSettings()
    if current == house.neighborhoodGUID and C_HousingNeighborhood then
        local plots = Call(C_HousingNeighborhood.GetNeighborhoodMapData)
        for _, plot in ipairs(type(plots) == "table" and plots or {}) do
            if plot.plotID == house.plotID and plot.mapPosition then
                local x, y = plot.mapPosition.x, plot.mapPosition.y
                if Number(x) and Number(y) and x >= 0 and x <= 1 and y >= 0 and y <= 1 then
                    local position = { space = "map", uiMapID = mapID, x = x, y = y }
                    settings.housingPositions = settings.housingPositions or {}
                    settings.housingPositions[house.houseGUID] = position
                    return APR.NavigationData:NormalizeLocation(position)
                end
            end
        end
    end
    local saved = settings.housingPositions and settings.housingPositions[house.houseGUID]
    if saved and saved.uiMapID == mapID then return self:SavedPosition(saved) end
    return nil
end--[[APR_DIAG]]; Adapter.GetHousingPosition = APRTrace("APR-Core/features/navigation/adapter/NavigationAdapterLocations.lua:195:Adapter:GetHousingPosition#10", Adapter.GetHousingPosition)--[[/APR_DIAG]]

function Adapter:UpdateHousingExitLocation()
    local position = PlayerPosition()
    if position then self:GetCharacterSettings().housingExitLocation = Copy(position) end
end--[[APR_DIAG]]; Adapter.UpdateHousingExitLocation = APRTrace("APR-Core/features/navigation/adapter/NavigationAdapterLocations.lua:221:Adapter:UpdateHousingExitLocation#11", Adapter.UpdateHousingExitLocation)--[[/APR_DIAG]]

function environment.getCurrentMapID()
    local mapID = APR.GetPlayerMapID and Call(APR.GetPlayerMapID, APR)
        or (C_Map and Call(C_Map.GetBestMapForUnit, "player"))
    if Number(mapID) then return mapID end
end--[[APR_DIAG]]; environment.getCurrentMapID = APRTrace("APR-Core/features/navigation/adapter/NavigationAdapterLocations.lua:226:environment.getCurrentMapID#12", environment.getCurrentMapID)--[[/APR_DIAG]]

function environment.getHousingInitiative(mapID)
    if not C_NeighborhoodInitiative or not C_Housing then return nil end
    local house = Adapter:GetHousingData()
    local current = Text(Call(C_Housing.GetCurrentNeighborhoodGUID))
    local wanted = current or (house and house.neighborhoodGUID)
    if not wanted then return nil end
    local actualMap = Call(C_Housing.GetUIMapIDForNeighborhood, wanted)
    if not Number(actualMap) or actualMap ~= mapID then return nil end
    local info = Call(C_NeighborhoodInitiative.GetNeighborhoodInitiativeInfo)
    if
        type(info) ~= "table"
        or not Accessible(info.isLoaded)
        or info.isLoaded ~= true
        or Text(info.neighborhoodGUID) ~= wanted
        or not Number(info.initiativeID)
        or not Number(info.currentCycleID)
        or not Number(info.duration)
        or info.duration <= 0
    then
        return nil
    end
    return {
        isLoaded = true,
        neighborhoodGUID = wanted,
        initiativeID = info.initiativeID,
        currentCycleID = info.currentCycleID,
    }
end--[[APR_DIAG]]; environment.getHousingInitiative = APRTrace("APR-Core/features/navigation/adapter/NavigationAdapterLocations.lua:232:environment.getHousingInitiative#13", environment.getHousingInitiative)--[[/APR_DIAG]]

